{"action": "write", "path": "duration.py", "content": "import re


_DURATION_RE = re.compile(
    r"\s*(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?\s*"
)

_UNIT_SECONDS = (
    ("d", 86400),
    ("h", 3600),
    ("m", 60),
    ("s", 1),
)


def parse_duration(s):
    """Parse a duration string into a number of seconds."""
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    match = _DURATION_RE.fullmatch(s)
    if match is None:
        raise ValueError(f"invalid duration: {s!r}")

    amounts = match.groups()
    if all(amount is None for amount in amounts):
        raise ValueError(f"invalid duration: {s!r}")

    total = 0
    for amount, (_, multiplier) in zip(amounts, _UNIT_SECONDS):
        if amount is not None:
            total += int(amount) * multiplier

    return total
